 const panel=document.createElement('div');panel.className='dialog-backdrop voice-backdrop';panel.innerHTML=`<section class="dialog-card card voice-capture ${todoMode?'todo-voice':'finance-voice'}" role="dialog" aria-modal="true" aria-labelledby="voiceTitle"><h2 id="voiceTitle">Dettatura vocale</h2><div class="voice-status"><span class="voice-live-dot" aria-hidden="true"></span><b data-voice-status>Attivazione del microfono…</b></div><div class="voice-meter" aria-hidden="true"><i></i><i></i><i></i><i></i><i></i></div><label class="voice-transcript-label">Testo riconosciuto<textarea data-voice-transcript rows="3" placeholder="Il testo apparirà qui mentre parli"></textarea></label><p class="voice-error" data-voice-error hidden></p><div class="dialog-actions"><button type="button" data-voice-confirm disabled>Fine / Conferma</button><button type="button" data-voice-retry class="secondary">Riprova</button><button type="button" data-voice-cancel class="secondary">Annulla</button></div></section>`;
