 let native=Capacitor.isNativePlatform(),recognition=null,ended=false,listenerHandles=[],captured='',nativeSessionPending=false,finishRequested=false,finalReady=false;
 const errors={PERMISSION_DENIED:'Permesso microfono negato. Apri Impostazioni Android → App → In Ordine → Autorizzazioni → Microfono e consenti l’accesso.',SERVICE_UNAVAILABLE:'Sul telefono non è disponibile un servizio di riconoscimento vocale in italiano.',LANGUAGE_NOT_SUPPORTED:'Il servizio vocale installato non supporta l’italiano. Scegli o installa un servizio vocale con lingua italiana nelle impostazioni Android.',LANGUAGE_UNAVAILABLE:'Il pacchetto vocale italiano non è disponibile sul telefono. Connettiti a Internet, installalo nelle impostazioni del servizio vocale e riprova.',NETWORK:'Il servizio vocale richiede una connessione non disponibile.',NETWORK_TIMEOUT:'Connessione al servizio vocale scaduta. Riprova.',NO_MATCH:'Non ho riconosciuto parole. Parla vicino al microfono e riprova.',NO_SPEECH:'Non ho sentito parole. Riprova quando sei pronto.',AUDIO_ERROR:'Android non riesce ad accedere al microfono. Controlla il permesso o chiudi le altre app che usano il microfono.',BUSY:'Il servizio vocale è già in uso. Riprova tra poco.',SERVER_ERROR:'Il servizio vocale Android ha restituito un errore. Riprova.',CLIENT_ERROR:'Android ha interrotto l’ascolto. Premi Riprova.',INTERRUPTED:'L’ascolto è stato interrotto. Premi Riprova.',START_FAILED:'Impossibile avviare il microfono. Riprova.'};
 const showError=(code,detail='')=>{status.textContent='Ascolto non disponibile';errorNode.textContent=errors[code]||detail||`Errore di riconoscimento (${code||'sconosciuto'}). Riprova o scrivi.`;errorNode.hidden=false;meter.classList.remove('is-listening','is-recognizing');confirmButton.disabled=!transcript.value.trim();confirmButton.textContent='Usa il testo'};
 const setState=state=>{if(ended)return;errorNode.hidden=true;meter.classList.toggle('is-listening',state==='recording');meter.classList.toggle('is-recognizing',state==='recognizing');if(state==='starting')status.textContent='Attivazione del microfono…';if(state==='ready')status.textContent='Parla ora';if(state==='recording')status.textContent='Sto ascoltando…';if(state==='recognizing')status.textContent='Sto riconoscendo la voce…';if(state==='review'){status.textContent='Testo pronto: controllalo prima di usarlo';finalReady=true;confirmButton.textContent='Usa il testo'}confirmButton.disabled=!transcript.value.trim()};
 const syncButton=()=>{if(button.isConnected){button.dataset.listening='false';button.setAttribute('aria-label',button.dataset.voiceCreate?'Aggiungi con la voce':'Avvia dettatura')}};
