 const startNative=async(retry=false)=>{setState('starting');try{if(retry&&nativeSessionPending){await NativeSpeechRecognition.retry()}else {await attachNativeEvents();activeRecognition={cancel:()=>NativeSpeechRecognition.cancel().catch(()=>{})};nativeSessionPending=true;NativeSpeechRecognition.listen({language:'it-IT'}).then(result=>{nativeSessionPending=false;if(!ended)apply(result?.transcript||transcript.value)}).catch(err=>{nativeSessionPending=false;if(!ended)showError(err?.code||'',err?.message||'')})}}catch(err){nativeSessionPending=false;showError(err?.code||'',err?.message||'')}};
 const startBrowser=(retry=false)=>{const Speech=window.SpeechRecognition||window.webkitSpeechRecognition;if(!Speech){showError('SERVICE_UNAVAILABLE','Il riconoscimento vocale non è disponibile in questo browser.');return}try{recognition=new Speech();activeRecognition=recognition;recognition.lang='it-IT';recognition.interimResults=true;recognition.continuous=true;recognition.maxAlternatives=1;recognition.onstart=()=>setState('ready');recognition.onspeechstart=()=>setState('recording');recognition.onspeechend=()=>setState('recognizing');recognition.onresult=event=>{let live='';for(let i=0;i<event.results.length;i++)live+=event.results[i][0].transcript+' ';captured=live.trim();transcript.value=captured;confirmButton.disabled=!captured;setState(event.results[event.results.length-1]?.isFinal?'review':'recording')};recognition.onerror=e=>showError(e.error||'RECOGNITION_ERROR');recognition.onend=()=>{if(ended)return;if(finishRequested&&transcript.value.trim()){finishRequested=false;finalReady=true;apply(transcript.value)}else if(transcript.value.trim())setState('review');else showError('NO_SPEECH')};recognition.start()}catch(e){showError('START_FAILED',String(e?.message||''))}};
 const retry=()=>{transcript.value='';captured='';finishRequested=false;finalReady=false;confirmButton.textContent='Fine / Conferma';errorNode.hidden=true;confirmButton.disabled=true;if(native)startNative(true);else startBrowser(true)};
