function setFormDate(prefix,fields){
  const mode=document.querySelector(`#${prefix}DateMode`);if(!mode){if(prefix==='money'&&fields.date){const input=document.querySelector('#moneyDate');if(input)input.value=fields.date}return;}
 const precision=fields.datePrecision||'none';mode.value=precision;
 const set=(suffix,value)=>{const input=document.querySelector(`#${prefix}${suffix}`);if(input)input.value=value||''};
 if(precision==='day')set('Date',fields.date);else if(precision==='month')set('Month',fields.date);else if(precision==='year')set('YearPart',fields.date);else if(precision==='dayMonth'){const [m,d]=fields.date.split('-');set('DayMonthMonth',m);set('DayMonthPart',Number(d))}
 syncDateMode(prefix);
}
function setVoiceRecurrence(prefix,rule){
 if(!rule)return;
  if(prefix==='money'){if(rule.unit==='month'){const choice=document.querySelector('#moneyRecurrenceMonthly');if(choice)choice.checked=true;const end=document.querySelector(`#moneyRecurrenceEnd${rule.end==='never'?'Never':'Count'}`);if(end)end.checked=true;const count=document.querySelector('#moneyRecurrenceCount');if(count&&rule.end!=='never')count.value=String(rule.count||12);syncMoneyRecurrenceMode()}return;}
 const selector=document.querySelector(`#${prefix}Recurrence`),interval=document.querySelector(`#${prefix}RecurrenceInterval`),unit=document.querySelector(`#${prefix}RecurrenceUnit`),end=document.querySelector(`#${prefix}RecurrenceEnd`);
 if(selector)selector.value=rule.interval>1?'custom':({day:'daily',week:'weekly',month:'monthly',year:'yearly'}[rule.unit]||'none');
 if(interval)interval.value=String(rule.interval||1);if(unit)unit.value=rule.unit;if(end)end.value=rule.end||'never';syncRecurrenceMode(prefix);
}
function reviewVoiceForm(prefix,fields,missing,kind){
 const get=id=>document.querySelector(`#${prefix}${id}`);
 if(get('Description'))get('Description').value=fields.description||'';
 if(get('Amount')&&Number.isFinite(fields.amount))get('Amount').value=String(fields.amount).replace('.',',');
 if(get('Category'))get('Category').value=fields.category||'';
 if(get('Supplier'))get('Supplier').value=fields.supplier||'';
 setFormDate(prefix,fields);
 setVoiceRecurrence(prefix,fields.recurrenceRule);
 const time=get('ReminderTime'),notify=get('Notify');if(fields.time&&time){time.value=fields.time;if(notify)notify.checked=true;syncReminderMode(prefix)}
 const labels={description:'descrizione',amount:'importo',date:'data', 'recurrence-anchor':'giorno di partenza della ricorrenza'};
 const missingText=missing.length?` Da completare: ${missing.map(x=>labels[x]||x).join(', ')}.`:'';
 const recognized=[kind==='todo'?'Attività':kind==='income'?'Entrata':'Pagamento',fields.description||'descrizione mancante'];if(kind!=='todo')recognized.push(Number.isFinite(fields.amount)?euro(fields.amount):'importo mancante');recognized.push(fields.date?formatDateValue(fields.date,fields.datePrecision):'senza data',fields.recurrenceRule?`${fields.recurrenceRule.interval>1?'ogni '+fields.recurrenceRule.interval+' ':''}${({day:'giorno',week:'settimana',month:'mese',year:'anno'}[fields.recurrenceRule.unit]||'ricorrente')}`:'senza ricorrenza');if(fields.category)recognized.push('categoria: '+fields.category);if(fields.supplier)recognized.push('fornitore/provenienza: '+fields.supplier);if(fields.time)recognized.push('orario: '+fields.time);
 speechMessage(`Dati riconosciuti: ${recognized.join(' · ')}.${missingText} Controllali e correggili qui, poi premi Salva. Nulla è stato salvato.`);
}
function applyVoiceEntry(kind,transcript){
 const parsed=parseItalianVoiceEntry(transcript,{kind:kind==='todo'?'todo':kind,categories:state.preferences.categories||defaultCategories});
 if(parsed.fields.recurrenceRule&&!parsed.fields.date)parsed.missing.push('recurrence-anchor');
 if(parsed.fields.time&&!parsed.fields.date&&!parsed.missing.includes('date'))parsed.missing.push('date');
 if(kind==='todo')todoAdd(parsed.fields,parsed.missing);else moneyForm(parsed.fields.typeExplicit?parsed.fields.kind:kind,parsed.fields,parsed.missing);
}

function landing(){const name=String(state.profile?.fullName||'').trim();shell('<section class="brand card"><div class="brand-top"><span class="eyebrow">IL TUO SPAZIO PERSONALE</span><img class="brand-logo" src="../assets/eds-blue-green-overlap.jpg" alt="E.D.S. blu e verde sovrapposti"></div><div class="brand-copy"><strong>In Ordine</strong><p>Conti e cose da fare, in un unico posto.</p></div><img class="hero-art home-art" src="../assets/inordine-home-couple.webp" alt="Una donna e un uomo sorridenti organizzano insieme la loro giornata"><div class="brand-ribbon">Più tempo per ciò che conta <span aria-hidden="true">♥</span></div></section><h2 class="home-section-title">Da dove vuoi iniziare?</h2><div class="home-paired-grid"><div class="home-pair"><button class="area-card money home-area" data-go="money"><img class="home-tile-art" src="../assets/conti-wallet-balance.webp" alt="Portafoglio blu e moneta"><b>Conti economici</b><small>Saldo, entrate, pagamenti e movimenti</small><span class="home-area-cta" aria-hidden="true">INIZIA <b>→</b></span></button><button class="home-pair-notice finance-notice" data-go="finance-notifications"><svg class="bell-icon" viewBox="0 0 24 24" aria-hidden="true"><path d="M18 8a6 6 0 0 0-12 0c0 7-3 7-3 9h18c0-2-3-2-3-9M10 21h4"/></svg>Notifiche Conti economici</button></div><div class="home-pair"><button class="area-card todo home-area" data-go="todo"><img class="home-tile-art" src="../assets/todo-couple-checklist.webp" alt="Lista delle attività"><b>Cose da fare</b><small>Attività, scadenze e promemoria</small><span class="home-area-cta" aria-hidden="true">INIZIA <b>→</b></span></button><button class="home-pair-notice todo-notice" data-go="todo-notifications"><svg class="bell-icon" viewBox="0 0 24 24" aria-hidden="true"><path d="M18 8a6 6 0 0 0-12 0c0 7-3 7-3 9h18c0-2-3-2-3-9M10 21h4"/></svg>Notifiche Cose da fare</button></div></div>'+(name?'<p class="home-greeting">Ciao, '+escapeHtml(name)+'!</p>':'<form id="homeNameForm" class="home-name-form"><label for="homeName">Come vuoi essere chiamato?</label><div><input id="homeName" name="name" type="text" required maxlength="80" autocomplete="name" placeholder="Il tuo nome"><button type="submit">Salva</button></div></form>')+'<p class="home-note">Un piccolo passo alla volta, tutto al suo posto.</p>')}
function monthName(ym){const [y,m]=ym.split('-').map(Number);return new Intl.DateTimeFormat('it-IT',{month:'long',year:'numeric'}).format(new Date(y,m-1,1))}
