const BACKUP_METADATA_KEY='inOrdineBackupMetadataV1';
function backupMetadata(){try{return JSON.parse(localStorage.getItem(BACKUP_METADATA_KEY)||'{}')}catch{return{}}}
function backupDateLabel(value){if(!value)return'';const date=new Date(value);return Number.isNaN(date.getTime())?'':new Intl.DateTimeFormat('it-IT',{dateStyle:'medium',timeStyle:'short'}).format(date)}
function backupMetadataMarkup(){const savedAt=backupMetadata().lastFileSavedAt;return `<p class="backup-cloud-status"><b>Ultimo backup verificato su Google Drive:</b> nessuno. In Ordine non è collegato a Drive e non può controllare lo stato del caricamento.</p>${savedAt?`<p class="backup-local-status">Ultimo file scritto e verificato nella destinazione scelta: ${escapeHtml(backupDateLabel(savedAt))}. Il caricamento cloud non è verificato.</p>`:'<p class="backup-local-status">Non risulta ancora un file di backup verificato da In Ordine.</p>'}`}
async function saveBackupMetadata(){try{localStorage.setItem(BACKUP_METADATA_KEY,JSON.stringify({lastFileSavedAt:new Date().toISOString()}))}catch(error){console.warn('Backup saved, but local backup history could not be updated.',error)}}
async function getBackupConnectionStatus(){const picker=nativePlugin('BackupFilePicker');if(picker){try{return await picker.getConnectionStatus()}catch{return{internetAvailable:null,transport:'unknown'}}}return{internetAvailable:typeof navigator!=='undefined'?navigator.onLine:null,transport:'unknown'}}
async function exportBackup(){const payload=JSON.stringify(await createBackup(state),null,2),picker=nativePlugin('BackupFilePicker');if(picker){const result=await picker.saveFile({fileName:backupFileName(),contents:payload});if(result?.cancelled)return null;if(!result?.saved)throw new Error('FILE_NOT_SAVED');return{saved:true,verified:true,fileName:result.fileName,bytes:result.bytes,connection:await getBackupConnectionStatus()}}if(window.showSaveFilePicker){const handle=await window.showSaveFilePicker({suggestedName:backupFileName(),types:[{description:'Backup In Ordine',accept:{'application/json':['.json']}}]}),writable=await handle.createWritable();await writable.write(new Blob([payload],{type:'application/json'}));await writable.close();const file=await handle.getFile();return{saved:true,verified:await file.text()===payload,fileName:handle.name,connection:await getBackupConnectionStatus()}}const blob=new Blob([payload],{type:'application/json'}),a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download=backupFileName();a.click();setTimeout(()=>URL.revokeObjectURL(a.href),2000);return{saved:false,downloadStarted:true,connection:await getBackupConnectionStatus()}}
async function exportTodoBackup(){const payload=JSON.stringify({format:'in-ordine-v2-todo',scope:'todo',exportedAt:new Date().toISOString(),todo:state.todo},null,2);const fs=nativePlugin('Filesystem'),share=nativePlugin('Share');if(fs&&share){const name='in-ordine-cose-da-fare-'+new Date().toISOString().slice(0,10)+'.json';await fs.writeFile({path:name,data:btoa(unescape(encodeURIComponent(payload))),directory:'CACHE'});const uri=await fs.getUri({path:name,directory:'CACHE'});await share.share({title:'Backup Cose da fare',url:uri.uri});return}const blob=new Blob([payload],{type:'application/json'}),a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download='in-ordine-cose-da-fare.json';a.click();setTimeout(()=>URL.revokeObjectURL(a.href),500)}
function todoBackupSettings(){shell('<header class="page-header todo-head"><button data-go="todo-settings">‹</button><div><small>COSE DA FARE</small><h1>Backup e ripristino</h1></div><img class="eds-logo" src="../assets/eds-green-approved.png" alt="E.D.S."></header><section class="card form-card"><p>Esporta le attività e le impostazioni delle Cose da fare. Il ripristino sostituisce solo i dati delle Cose da fare dopo la tua conferma; Conti economici e profilo restano invariati.</p><button type="button" id="exportTodoBackup">Esporta backup</button><label class="import-label">Ripristina backup<input id="importTodoBackup" type="file" accept="application/json,.json"></label></section>')}
