function securitySettings(back='settings'){const todoMode=back==='todo-settings';shell('<header class="page-header '+(todoMode?'todo-head':'')+'"><button data-go="'+back+'">‹</button><div><small>'+(todoMode?'COSE DA FARE':'IMPOSTAZIONI')+'</small><h1>Sicurezza</h1></div>'+(todoMode?'<img class="eds-logo" src="../assets/eds-green-approved.png" alt="E.D.S.">':'<span class="eds">E.D.S.</span>')+'</header><section class="card form-card" data-security-return="'+back+'"><label class="check"><input id="biometricEnabled" type="checkbox" '+(state.preferences.biometricEnabled?'checked':'')+'> Proteggi l’app con biometria</label><p class="hint">Se disponibile sul dispositivo, In Ordine richiederà impronta o riconoscimento biometrico all’avvio.</p><button id="saveSecurity" type="button">Salva sicurezza</button></section>')}
async function authenticateIfNeeded(){if(!state.preferences?.biometricEnabled)return true;if(!Capacitor.isNativePlatform())return false;const bio=nativePlugin('NativeBiometric');if(!bio)return false;try{const available=await bio.isAvailable();if(!available?.isAvailable)return false;await bio.verifyIdentity({reason:'Accedi a In Ordine',title:'In Ordine',subtitle:'Conferma la tua identità'});return true}catch{return false}}
