function backupSettings(back='settings'){shell('<header class="page-header"><button data-go="'+back+'">‹</button><div><small>IMPOSTAZIONI</small><h1>Backup e ripristino</h1></div><span class="eds">E.D.S.</span></header><section class="card form-card backup-settings-card"><button type="button" class="wide" id="openSaveBackup">SALVA I MIEI DATI</button><button type="button" class="wide secondary" id="openRestoreBackup">RECUPERA I MIEI DATI</button>'+backupMetadataMarkup()+'<p class="backup-limit-note">Per ora Android apre il selettore file. Se scegli Google Drive, il file può restare in attesa di Wi-Fi o connessione: In Ordine non può vedere né modificare la coda di caricamento di Drive. Per trasferimenti mobili, controlla le impostazioni di rete nell’app Google Drive.</p><input id="importBackup" type="file" accept="application/json,.json" hidden><p id="backupStatus" role="status" aria-live="polite"></p></section>')}
function backupExplanation(){backupSettings()}
function firstRun(){shell('<section class="card form-card backup-intro"><h1>Bentornato su In Ordine!</h1><p>Hai già utilizzato questa app?</p><p>Se avevi salvato una copia dei tuoi dati, puoi recuperarli selezionando il file su Drive o sul telefono.</p><p>La ricerca automatica in Google Drive non è disponibile finché In Ordine non viene collegato a Google.</p><button type="button" id="firstRunStart">INIZIA DA ZERO</button><button type="button" class="secondary" id="firstRunRestore">RECUPERA I MIEI DATI</button></section>')}
