function storageErrorScreen(){shell('<section class="card empty locked"><h1>I dati non si aprono</h1><p>Ho conservato il file dei dati senza modificarlo. Se hai una copia di backup, puoi recuperarla qui.</p><button type="button" id="recoverUnreadableData">RECUPERA I MIEI DATI</button></section>')}
function showBackupError(error){const messages={FILE_INVALID:'Questo file non è leggibile o non è un backup JSON valido. I dati presenti sono rimasti invariati.',FILE_DAMAGED:'Il file sembra danneggiato. I dati presenti sono rimasti invariati.',DATA_MISSING:'Nel file non trovo i dati da recuperare. I dati presenti sono rimasti invariati.',DATA_INCOMPLETE:'Il file non contiene tutte le informazioni necessarie. I dati presenti sono rimasti invariati.',FORMAT_UNSUPPORTED:'Questo backup è di un formato non compatibile. I dati presenti sono rimasti invariati.',FILE_TOO_LARGE:'Il file è troppo grande per essere letto. I dati presenti sono rimasti invariati.',STORAGE_READ_FAILED:'Non riesco a leggere i dati attuali. Non li ho modificati.',RESTORE_VERIFY_FAILED:'Non è stato possibile verificare il ripristino. Ho conservato i dati precedenti.'};const text=messages[error?.message]||'Non è stato possibile salvare o recuperare i dati. I dati presenti sono rimasti invariati.';const status=document.querySelector('#backupStatus');if(status)status.textContent=text;else alert(text)}
function stableBackupValue(value){if(Array.isArray(value))return value.map(stableBackupValue);if(value&&typeof value==='object')return Object.fromEntries(Object.keys(value).sort().map(key=>[key,stableBackupValue(value[key])]));return value}
function hasSavedUserData(value){const current=structuredClone(value);current.welcomeCompleted=false;return JSON.stringify(stableBackupValue(current))!==JSON.stringify(stableBackupValue(createEmptyState()))}
async function restoreBackupText(text){const candidate=await readBackupText(text);if(hasSavedUserData(state)&&!confirm('Il recupero sostituirà le informazioni presenti in In Ordine con quelle del salvataggio. Prima di procedere ho preparato una protezione dei dati attuali. Vuoi continuare?'))return false;candidate.welcomeCompleted=true;migrateLegacyRecurrences(candidate);stripDailySummarySettings(candidate);state=await restoreStateSafely(candidate);applyPreferences();let reminderSyncFailed=false;try{const result=await syncTodoNotifications();reminderSyncFailed=result.status==='failed'}catch(error){console.warn('Backup restored, but notification synchronization failed.',error);reminderSyncFailed=true}shell('<section class="card form-card backup-intro"><h1>Dati recuperati!</h1><p>Ora puoi continuare da dove avevi lasciato.</p><button type="button" id="continueAfterRestore">Continua</button></section>');if(reminderSyncFailed)document.querySelector('.backup-intro')?.insertAdjacentHTML('beforeend','<p>Le informazioni sono state recuperate, ma non è stato possibile aggiornare i promemoria Android. Controlla le notifiche nelle impostazioni.</p>');return true}
async function chooseBackupFile(){const picker=nativePlugin('BackupFilePicker');if(picker){const result=await picker.openFile();if(result?.cancelled)return;if(typeof result?.contents!=='string')throw new Error('FILE_INVALID');await restoreBackupText(result.contents);return}document.querySelector('#importBackup')?.click()}
function backupSaveResult(result){if(result?.downloadStarted){shell('<section class="card form-card backup-result"><h1>DOWNLOAD AVVIATO</h1><p>Il browser ha avviato il download. Controlla che il file sia presente nei download prima di considerare al sicuro la copia.</p><p>Ultimo backup verificato su Google Drive: nessuno. In Ordine non può controllare il caricamento cloud.</p><button type="button" id="backupResultContinue">CONTINUA</button></section>');return}const offline=result?.connection?.internetAvailable===false;const online=result?.connection?.internetAvailable===true;const connectionMessage=offline?'Il telefono non segnala una connessione Internet. Il file è stato scritto nella destinazione scelta, ma nessun caricamento online è stato verificato.':online?'Il telefono segnala una connessione Internet, ma questo non conferma il caricamento su Google Drive.':'Non è stato possibile controllare la connessione Internet.';const mobileMessage=result?.connection?.transport==='mobile'?' È attiva una connessione dati mobile; Google Drive può comunque sospendere i caricamenti se è impostato per usare solo il Wi-Fi.':'';shell(`<section class="card form-card backup-result"><div class="backup-result-check" aria-hidden="true">✓</div><h1>FILE SALVATO</h1><p>In Ordine ha scritto e riletto la copia nella destinazione scelta.</p><p><b>Il caricamento su Google Drive non è verificato.</b> ${connectionMessage}${mobileMessage}</p><p>Se hai scelto Drive, apri l’app Google Drive e controlla che il caricamento sia terminato. Se è in attesa, In Ordine non può riprenderlo: verifica le impostazioni di rete di Drive e riprova da lì.</p><p><b>Ultimo backup verificato su Google Drive:</b> nessuno.</p><button type="button" id="backupResultContinue">CONTINUA</button></section>`)}
async function performBackupSave(){try{const result=await exportBackup();if(!result){backupSettings();return}if(result.verified)await saveBackupMetadata();backupSaveResult(result)}catch(error){showBackupError(error)}}
function monthHistory(kind,ym=monthKey()){return financeCompletedEntries(state).filter(x=>x.kind===kind&&matchesMonth(x,ym))}
function summary(){const ym=monthKey(),inc=monthHistory('income',ym).reduce((s,x)=>s+Number(x.amount||0),0),exp=monthHistory('expense',ym).reduce((s,x)=>s+Number(x.amount||0),0),prev=addMonths(ym,-1),prevInc=monthHistory('income',prev).reduce((s,x)=>s+Number(x.amount||0),0),prevExp=monthHistory('expense',prev).reduce((s,x)=>s+Number(x.amount||0),0);shell('<header class="page-header money-head"><button data-go="money">‹</button><div><small>CONTI ECONOMICI</small><h1>Riepilogo</h1></div><span class="eds">E.D.S.</span></header><section class="balance card"><small>Saldo reale</small><strong>'+euro(realBalance())+'</strong></section><div class="area-grid"><div class="area-card income"><b>Entrate ricevute</b><strong>'+euro(inc)+'</strong></div><div class="area-card expense"><b>Pagamenti effettuati</b><strong>'+euro(exp)+'</strong></div></div><section class="card summary-card"><div class="summary-difference"><b>Differenza movimenti</b><strong>'+euro(inc-exp)+'</strong></div><small>'+monthName(ym)+'</small></section><section class="card compare"><b>Confronto con '+monthName(prev)+'</b><p>Entrate: '+euro(inc)+' · mese precedente '+euro(prevInc)+' · variazione '+euro(inc-prevInc)+'</p><p>Pagamenti: '+euro(exp)+' · mese precedente '+euro(prevExp)+' · variazione '+euro(exp-prevExp)+'</p></section><button class="wide card" data-go="budget">Apri budget</button>')}
function todo(){const pending=state.todo.tasks.length,done=state.todo.done.length;shell('<div class="todo-home-screen"><header class="page-header todo-head"><button data-go="landing" aria-label="Torna alla home">‹</button><div><small>PIANIFICA CON CALMA</small><h1>Cose da fare</h1></div><img class="eds-logo" src="../assets/eds-green-approved.png" alt="E.D.S."></header><section class="todo-hero card"><div class="todo-art-frame"><img class="section-art todo-art" src="../assets/todo-couple-checklist.webp" alt="Una coppia organizza attività e promemoria con una lista, un orologio e una campanella"></div><p>Piccoli passi, grandi soddisfazioni.</p></section><h2 class="section-kicker todo-kicker">La tua giornata, con più leggerezza</h2><div class="area-grid todo-areas"><button class="area-card pending" data-go="todo-active"><span class="tile-icon" aria-hidden="true">◷</span><b>In scadenza</b><strong>'+pending+'</strong><small>Attività ancora da fare</small><span class="todo-area-cta"><span>INIZIA</span><i aria-hidden="true">→</i></span><span class="tile-arrow" aria-hidden="true">›</span></button><button class="area-card completed" data-go="todo-done"><span class="tile-icon" aria-hidden="true">✓</span><b>Cose già fatte</b><strong>'+done+'</strong><small>Ogni piccolo traguardo</small><span class="todo-area-cta"><span>INIZIA</span><i aria-hidden="true">→</i></span><span class="tile-arrow" aria-hidden="true">›</span></button></div><button class="wide card primary-action" data-go="todo-add"><span class="action-plus" aria-hidden="true">+</span><span>Aggiungi cosa da fare</span><b aria-hidden="true">›</b></button><button class="wide card settings-action" data-go="todo-notifications"><span class="link-icon">♧</span><span>Notifiche<small>Orari e anticipi personalizzati</small></span><b aria-hidden="true">›</b></button><button class="wide card settings-action" data-go="todo-settings"><span class="link-icon">⚙</span><span>Impostazioni<small>Colori e notifiche</small></span><b aria-hidden="true">›</b></button><button class="wide card settings-action domain-reset-action todo-reset-action" id="resetTodo"><span class="link-icon">⌫</span><span>Cancella tutte le cose da fare inserite</span><b aria-hidden="true">›</b></button></div>')}
function expandRecurring(entry){if(!entry.recurrenceRule||!entry.date)return;addOccurrences(state.entries,entry,entry.recurrenceRule,entry.datePrecision||'day')}
let todoListDone=false;const todoVisibleMonth={active:'',done:''};
function todoMonthKey(item){const f=dateFields(item),now=new Date(),year=Number.isInteger(f.year)?f.year:now.getFullYear(),month=Number.isInteger(f.month)?f.month:(f.precision==='dayOnly'?now.getMonth()+1:null);return month?`${year}-${String(month).padStart(2,'0')}`:''}
function todoMonthLabel(key){const [year,month]=key.split('-').map(Number);return new Intl.DateTimeFormat('it-IT',{month:'long',year:'numeric'}).format(new Date(year,month-1,1)).toLocaleUpperCase('it-IT')}
function todoSortValue(item){const f=dateFields(item),key=todoMonthKey(item);if(!key)return '9999-99-99';return `${key}-${String(Number.isInteger(f.day)?f.day:1).padStart(2,'0')}`}
function todoMonthControls(monthKeys,done){const mode=done?'done':'active',today=monthKey(),selected=todoVisibleMonth[mode]||today;todoVisibleMonth[mode]=selected;const index=monthKeys.indexOf(selected),canGoBack=index>=0?index>0:monthKeys.some(key=>key<selected),canGoForward=index>=0?index<monthKeys.length-1:monthKeys.some(key=>key>selected);return '<div class="todo-month-nav month-nav card" data-todo-month-nav="'+mode+'"><button type="button" data-todo-month-step="-1" aria-label="Mese precedente" '+(!canGoBack?'disabled':'')+'>‹</button><b data-todo-month-label>'+todoMonthLabel(selected)+'</b><button type="button" data-todo-month-step="1" aria-label="Mese successivo" '+(!canGoForward?'disabled':'')+'>›</button></div>'}
function orderedTodos(items,done){return items.map(item=>done&&item.completedAt?{...item,date:item.completedAt.slice(0,10),datePrecision:'day'}:{...item}).sort((a,b)=>todoSortValue(a).localeCompare(todoSortValue(b))||String(a.createdAt||'').localeCompare(String(b.createdAt||'')))}
function shiftDateSafe(date,rule,i){const [y,m,d]=date.split('-').map(Number);if(rule==='monthly'){const target=new Date(y,m-1+i,1,12);const last=new Date(target.getFullYear(),target.getMonth()+1,0).getDate();target.setDate(Math.min(d,last));return target.toISOString().slice(0,10)}if(rule==='yearly'){const targetYear=y+i,last=new Date(targetYear,m,0).getDate();return targetYear+'-'+String(m).padStart(2,'0')+'-'+String(Math.min(d,last)).padStart(2,'0')}return date}
function recurrenceDates(date,rule,count=24){if(!date||rule==='none')return[];const out=[];for(let i=1;i<=count;i++)out.push(shiftDateSafe(date,rule,i));return out}
function moneyTotals(kind,ym){return financeTotals(state,kind,ym)}
function todoAdd(voiceFields=null,missing=[]){shell(`<header class="page-header todo-head"><button data-go="todo">‹</button><div><small>COSE DA FARE</small><h1>Nuova attività</h1></div><span class="eds">E.D.S.</span></header><form id="todoForm" class="card form-card"><label class="voice-field">Cosa devi fare?<input id="todoDescription" required autocomplete="off"><button type="button" class="voice-button" data-voice-target="todoDescription" aria-label="Detta descrizione attività"><svg viewBox="0 0 24 24" aria-hidden="true"><rect x="9" y="2" width="6" height="12" rx="3"/><path d="M5 11a7 7 0 0 0 14 0M12 18v4M8 22h8"/></svg></button></label>${dateControls('todo',{datePrecision:'day'})}${recurrenceFields('todo')}${reminderControls('todo',{},'todo')}<button type="submit">Salva attività</button></form>`);syncDateMode('todo');syncRecurrenceMode('todo');syncReminderMode('todo');if(voiceFields)reviewVoiceForm('todo',voiceFields,missing,'todo')}
function todoEdit(id,done=false){const list=done?state.todo.done:state.todo.tasks,x=list.find(t=>t.id===id);if(!x)return todoList(done);const recurring=Boolean(x.seriesId||x.recurrenceRule||x.recurrenceSource);shell(`<header class="page-header todo-head"><button data-go="${done?'todo-done':'todo-active'}">‹</button><div><small>COSE DA FARE</small><h1>Modifica attività</h1></div><span class="eds">E.D.S.</span></header><form id="todoEditForm" data-id="${x.id}" data-done="${done}" data-series="${recurring}" class="card form-card"><label class="voice-field">Descrizione<input id="todoEditDescription" value="${escapeHtml(x.description)}" required><button type="button" class="voice-button" data-voice-target="todoEditDescription" aria-label="Detta descrizione attività"><svg viewBox="0 0 24 24" aria-hidden="true"><rect x="9" y="2" width="6" height="12" rx="3"/><path d="M5 11a7 7 0 0 0 14 0M12 18v4M8 22h8"/></svg></button></label>${dateControls('todoEdit',x)}${recurrenceFields('todoEdit',x)}${reminderControls('todoEdit',x,'todo')}<button type="submit">Salva modifiche</button><button type="button" class="danger" data-delete-task="${x.id}" data-done="${done}">Elimina attività</button></form>`);syncDateMode('todoEdit');syncRecurrenceMode('todoEdit');syncReminderMode('todoEdit')}
function todoList(done=false){
  todoListDone=done;
  const source=done?state.todo.done:state.todo.tasks;
  const items=orderedTodos(source,done);
  const groupKey=x=>done?((x.completedAt||'').slice(0,10)||x.date||'no-date'):(x.datePrecision||'day')+':'+(x.date||'no-date');
  const byMonth=new Map(),withoutMonth=[];
  for(const item of items){const key=todoMonthKey(item);if(!key){withoutMonth.push(item);continue}if(!byMonth.has(key))byMonth.set(key,[]);byMonth.get(key).push(item)}
  const monthKeys=[...byMonth.keys()].sort();
  const renderDateGroups=monthItems=>{const groups=new Map();for(const item of monthItems){const key=groupKey(item);if(!groups.has(key))groups.set(key,[]);groups.get(key).push(item)}return [...groups.values()].map(group=>{const first=group[0],completionDate=(first.completedAt||'').slice(0,10);const heading=done?(completionDate?fmtTodoDate(completionDate,'day'):fmtTodoDate(first.date,first.datePrecision)):fmtTodoDate(first.date,first.datePrecision);const tasks=group.map(x=>'<article class="todo-item-card" data-edit-task="'+x.id+'" data-done="'+done+'"><div class="todo-task-main">'+(done?'<span class="todo-done-check" aria-label="Completata">✓</span>':'<button type="button" class="todo-list-bell'+(effectiveReminder(x,'todo',state).enabled?' is-notification-active':'')+'" data-reminder-open="todo" data-reminder-id="'+x.id+'" aria-label="Imposta notifica per '+escapeHtml(x.description)+'" title="Imposta notifica">'+filledBell()+'</button>')+'<span class="todo-task-name">'+escapeHtml(x.description)+'</span></div><div class="todo-task-actions">'+(!done&&isOverdue(x)?'<span class="overdue-label">SCADUTO</span>':'')+(done?'<button type="button" class="todo-restore-action" data-restore="'+x.id+'" aria-label="Rimetti tra le cose da fare" title="Rimetti tra le cose da fare">Rimetti tra le cose da fare</button>':'<button type="button" data-complete="'+x.id+'" class="todo-complete"><span aria-hidden="true">○</span> Segna come fatta</button>')+'</div></article>').join('');return '<section class="todo-date-group '+(done?'completed':'pending')+'" data-date-group="'+escapeHtml(groupKey(first))+'"><div class="todo-date-heading">'+escapeHtml(heading)+'</div>'+tasks+'</section>'}).join('')};
  const rows=monthKeys.map(key=>'<section class="todo-month-section '+(done?'completed':'pending')+'" data-todo-month="'+key+'"><h2 class="todo-month-heading">'+todoMonthLabel(key)+'</h2>'+renderDateGroups(byMonth.get(key))+'</section>').join('')+(withoutMonth.length?'<section class="todo-month-section todo-no-month '+(done?'completed':'pending')+'"><h2 class="todo-month-heading">SENZA MESE</h2>'+renderDateGroups(withoutMonth)+'</section>':'')||'<div class="card empty"><b>Nessuna attività</b><p>'+(done?'Le attività completate compariranno qui.':'Aggiungi la prima cosa da fare.')+'</p></div>';
  const activeLink='<button class="todo-nav-link todo-nav-link-done" data-go="todo-done"><span class="todo-nav-wave todo-nav-wave-top" aria-hidden="true"></span><span class="todo-nav-wave todo-nav-wave-bottom" aria-hidden="true"></span><span class="todo-nav-icon todo-nav-calendar" aria-hidden="true"><svg viewBox="0 0 24 24"><path d="M5 4h14a1.5 1.5 0 0 1 1.5 1.5v13A1.5 1.5 0 0 1 19 20H5a1.5 1.5 0 0 1-1.5-1.5v-13A1.5 1.5 0 0 1 5 4Z"/><path d="M8 2.8v3M16 2.8v3M3.5 8.5h17M7 12h2m2.5 0h2m2.5 0h1M7 15.5h2m2.5 0h2m2.5 0h1"/></svg></span><span class="todo-nav-copy"><b>Vedi cose già fatte</b><small>Visualizza tutte le cose che hai completato</small></span><span class="todo-nav-arrow" aria-hidden="true">›</span></button>';
  const doneLink='<button class="todo-nav-link todo-nav-link-active" data-go="todo-active"><span class="todo-nav-wave todo-nav-wave-top" aria-hidden="true"></span><span class="todo-nav-wave todo-nav-wave-bottom" aria-hidden="true"></span><span class="todo-nav-icon todo-nav-calendar" aria-hidden="true"><svg viewBox="0 0 24 24"><path d="M5 4h14a1.5 1.5 0 0 1 1.5 1.5v13A1.5 1.5 0 0 1 19 20H5a1.5 1.5 0 0 1-1.5-1.5v-13A1.5 1.5 0 0 1 5 4Z"/><path d="M8 2.8v3M16 2.8v3M3.5 8.5h17M7 12h2m2.5 0h2m2.5 0h1M7 15.5h2m2.5 0h2m2.5 0h1"/></svg></span><span class="todo-nav-copy"><b>Vedi cose in scadenza</b><small>Visualizza tutte le cose ancora da fare</small></span><span class="todo-nav-arrow" aria-hidden="true">›</span></button>';
  const addAction='<button class="wide card add-action todo-add-action list-create-action" data-go="todo-add"><span class="action-plus" aria-hidden="true">+</span><span>Aggiungi cosa da fare</span><b aria-hidden="true">›</b></button>';
  const footer=done?doneLink:addAction+activeLink;
  shell('<div class="todo-list-screen '+(done?'completed-list':'pending-list')+'"><header class="page-header todo-head"><button data-go="todo">‹</button><div><small>COSE DA FARE</small><h1>'+(done?'Già fatte':'In scadenza')+'</h1></div><span class="eds">E.D.S.</span></header>'+todoMonthControls(monthKeys,done)+rows+footer+'</div>');todoIgnoreProgrammaticScrollUntil=Date.now()+800;window.scrollTo(0,0)
}
function syncTodoMonthFromScroll(){const screen=document.querySelector('.todo-list-screen');if(!screen)return;const mode=screen.classList.contains('completed-list')?'done':'active',nav=screen.querySelector('[data-todo-month-nav]'),sections=[...screen.querySelectorAll('[data-todo-month]')];if(!nav||!sections.length)return;const anchor=80;let current=sections[0],nearest=Infinity;for(const section of sections){const distance=Math.abs(section.getBoundingClientRect().top-anchor);if(distance<nearest){nearest=distance;current=section}}const key=current.dataset.todoMonth;if(todoVisibleMonth[mode]!==key){todoVisibleMonth[mode]=key;nav.querySelector('[data-todo-month-label]').textContent=todoMonthLabel(key)}const index=sections.findIndex(section=>section.dataset.todoMonth===key);nav.querySelector('[data-todo-month-step="-1"]').disabled=index<=0;nav.querySelector('[data-todo-month-step="1"]').disabled=index<0||index>=sections.length-1}
let todoScrollSyncQueued=false,todoIgnoreProgrammaticScrollUntil=0;const markTodoManualScroll=()=>{todoIgnoreProgrammaticScrollUntil=0};window.addEventListener('wheel',markTodoManualScroll,{passive:true});window.addEventListener('touchstart',markTodoManualScroll,{passive:true});window.addEventListener('pointerdown',markTodoManualScroll,{passive:true});window.addEventListener('scroll',()=>{if(Date.now()<todoIgnoreProgrammaticScrollUntil||todoScrollSyncQueued)return;todoScrollSyncQueued=true;requestAnimationFrame(()=>{todoScrollSyncQueued=false;syncTodoMonthFromScroll()})},{passive:true});
function escapeHtml(v){return String(v??'').replace(/[&<>"']/g,ch=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[ch]))}
