function route(name){if(name==='first-run-name'||name==='landing')landing();else if(name==='welcome')firstRun();else if(name==='restore-intro')restoreIntro();else if(name==='backup-explain')backupExplanation();else if(name==='storage-error')storageErrorScreen();else if(name==='money')money();else if(name==='todo')todo();else if(name==='income'||name==='expense'){flowMonths[name]=monthKey();flow(name)}else if(name==='movements')movements();else if(name==='summary')summary();else if(name==='budget')budget();else if(name==='budget-categories')budgetCategory();else if(name==='categories')categorySettings();else if(name==='profile')profileSettings();else if(name==='preferences')preferencesSettings();else if(name==='security')securitySettings();else if(name==='todo-security')securitySettings('todo-settings');else if(name==='settings')settings();else if(name==='appearance')appearanceSettings();else if(name==='backup')backupSettings();else if(name==='todo-settings')todoSettings();else if(name==='todo-notifications')todoNotificationSettings();else if(name==='todo-settings-color')todoColorSettings();else if(name==='todo-backup')backupSettings('todo-settings');else if(name==='todo-profile')todoProfileSettings();else if(name==='finance-notifications')financeNotificationSettings();else if(name==='todo-add')todoAdd();else if(name==='todo-active'){todoVisibleMonth.active='';todoList(false)}else if(name==='todo-done'){todoVisibleMonth.done='';todoList(true)}else placeholder(({income:'Entrate',expense:'Pagamenti',movements:'Movimenti',summary:'Riepilogo e budget','todo-active':'In scadenza','todo-done':'Cose già fatte','todo-add':'Nuova attività','todo-settings':'Impostazioni'})[name]||'In Ordine',name.startsWith('todo-')?'todo':'money')}
